function [m] = residual_dipole_axes(dres)
%RESIDUAL_DIPOLE_AXES  The residual dipole [A m^2] along each body axis: the case's magnitude dres split evenly, dres/sqrt(3) on each.
%   dres: real[1] (passed a plain number)
%   returns m: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 1);
    h__151 = 3;
    if h__151 < 0, h__151 = NaN; else, h__151 = sqrt(h__151); end
    c = (dres / h__151);
    m = [c; c; c];
end
